/* ─────────────────────────────────────────────────────────────────────────
   CYBER SAMACHAR — INDIAN CYBER LAW REFERENCE
   Comprehensive section-wise reference. Editorial summary; not legal advice.
   Last updated: April 2026.
   Schema per section: { num, title, desc, pen, cog, bail, court, cases?, related?, notes? }
   ───────────────────────────────────────────────────────────────────────── */

const LAWS = [
/* ============================================================
   1. INFORMATION TECHNOLOGY ACT, 2000
   ============================================================ */
{
 id:'it2000', kind:'it', short:'IT Act', year:'2000 (amended 2008, 2023)',
 title:'Information Technology Act, 2000',
 sub:'India\'s primary cyber-law statute. Provides legal recognition to electronic records and digital signatures, defines cyber offences and contraventions, prescribes civil and criminal liability, establishes adjudicating officers, the Cyber Appellate Tribunal (now TDSAT), CERT-In and the framework for protected systems. Substantially amended by the IT (Amendment) Act, 2008 — which introduced §§ 43A, 66-series, 67A, 67B, 69, 69A, 70B, and intermediary safe-harbour under §79.',
 sections:[
  {num:'§ 1', title:'Short title, extent, commencement & application', desc:'Extends to whole of India and applies to any offence committed outside India by any person if the act involves a computer, computer system or computer network located in India. Came into force 17 Oct 2000.', pen:'—', cog:'—', bail:'—', court:'—',
    notes:'Extra-territorial reach in §1(2) read with §75 — basis for prosecuting overseas threat actors who target Indian systems.'},
  {num:'§ 2', title:'Definitions', desc:'Defines key terms — "access", "addressee", "computer", "computer network", "computer resource", "computer system", "data", "electronic record", "intermediary", "originator", "secure system", "subscriber". Foundational for every offence and obligation under the Act.', pen:'—', cog:'—', bail:'—', court:'—',
    notes:'"Communication device" was inserted in 2008 to cover mobile phones. "Intermediary" definition is broad and forms the basis of §79 safe harbour.'},
  {num:'§ 3 / 3A', title:'Authentication of electronic records', desc:'§3: digital-signature authentication using asymmetric crypto + hash function. §3A: electronic-signature authentication using any technique notified in the Second Schedule (e.g. e-Sign / Aadhaar-based eSign).', pen:'—', cog:'—', bail:'—', court:'—'},
  {num:'§ 4 / 5', title:'Legal recognition of e-records & e-signatures', desc:'§4: where law requires writing, an electronic record satisfies it if accessible for subsequent reference. §5: electronic signatures are legally equivalent to handwritten ones for any purpose required by law.', pen:'—', cog:'—', bail:'—', court:'—',
    cases:['Trimex International v. Vedanta (2010) 3 SCC 1 — emails constituting valid contract']},
  {num:'§ 10A', title:'Validity of contracts formed through electronic means', desc:'A contract is not unenforceable merely because it was concluded via electronic means — covers click-wrap, browse-wrap, EDI and electronic acceptance.', pen:'—', cog:'—', bail:'—', court:'—'},
  {num:'§ 43', title:'Penalty & compensation — damage to computer / system', desc:'Civil liability for unauthorised access, downloading, virus introduction, denial of access, tampering, manipulating accounts, destroying / altering / concealing computer source code, damage by any means — committed without permission of the owner. Adjudicated by an Adjudicating Officer under §46.', pen:'Compensation up to ₹5 crore (Adjudicating Officer); above ₹5 cr — Civil Court', cog:'—', bail:'—', court:'Adjudicating Officer (IT Secretary, State)',
    cases:['Umashankar Sivasubramanian v. ICICI Bank (Adj. Off., TN, 2010)','Sanjay Kaushik v. NIIT Tech (Cyber AT, 2014)'],
    notes:'Strict-liability civil tort. No requirement to prove dishonest / fraudulent intent — that\'s the difference from §66.'},
  {num:'§ 43A', title:'Compensation for failure to protect SPDI', desc:'A "body corporate" possessing, dealing or handling sensitive personal data or information (SPDI) — passwords, financial info, health condition, biometric, sexual orientation — that is negligent in implementing and maintaining "reasonable security practices" under SPDI Rules 2011, and causes wrongful loss/gain to any person, is liable to pay damages.', pen:'Unlimited compensation (no statutory cap)', cog:'—', bail:'—', court:'Adjudicating Officer / Civil Court',
    related:['SPDI Rules 2011','DPDP Act 2023 §8'],
    notes:'§43A will be repealed once DPDP §8 is fully notified, but remains in force for incidents pre-notification.'},
  {num:'§ 65', title:'Tampering with computer source documents', desc:'Knowingly or intentionally concealing, destroying, altering or causing another to do so to any computer source code that is required to be kept or maintained by law for the time being in force.', pen:'Up to 3 years imprisonment and/or fine up to ₹2 lakh', cog:'Y', bail:'Y', court:'Magistrate of First Class',
    cases:['Syed Asifuddin v. State of AP (2005) — first Indian source-code tampering conviction (Reliance ↔ Tata Indicom CDMA cloning)']},
  {num:'§ 66', title:'Computer-related offences (criminal hacking)', desc:'Whoever, dishonestly or fraudulently, does any act referred to in §43 — unauthorised access, downloading data, denial-of-service, virus introduction, source-code damage, etc. Adds the criminal mens rea (§24 IPC / §28 BNS dishonestly + §25 IPC / §29 BNS fraudulently) on top of the §43 conduct.', pen:'Up to 3 years imprisonment and/or fine up to ₹5 lakh', cog:'Y', bail:'Y', court:'Magistrate of First Class',
    related:['§ 43 (civil counterpart)','BNS § 318 / § 319']},
  {num:'§ 66A', title:'[STRUCK DOWN] Sending offensive messages', desc:'Originally criminalised "grossly offensive" or "menacing" messages sent through a computer resource. Struck down in entirety as unconstitutional for being vague and over-broad.', pen:'Struck down — no offence', cog:'—', bail:'—', court:'—',
    cases:['Shreya Singhal v. Union of India (2015) 5 SCC 1 — landmark free-speech judgment'],
    notes:'Continues to be wrongly invoked by some police stations — Supreme Court has issued repeated directions (PUCL v. UoI 2019, 2021, 2022) to stop its registration.'},
  {num:'§ 66B', title:'Receiving stolen computer resource or device', desc:'Dishonestly receiving or retaining any stolen computer resource or communication device, knowing or having reason to believe it to be stolen.', pen:'Up to 3 years and/or fine up to ₹1 lakh', cog:'Y', bail:'Y', court:'Magistrate'},
  {num:'§ 66C', title:'Identity theft', desc:'Fraudulent or dishonest use of any other person\'s electronic signature, password, or any other unique identification feature (incl. Aadhaar number, biometrics, OTP, login credentials, digital certificate).', pen:'Up to 3 years and fine up to ₹1 lakh', cog:'Y', bail:'Y', court:'Magistrate',
    related:['BNS § 319','Aadhaar Act §29 / §37']},
  {num:'§ 66D', title:'Cheating by personation using a computer resource', desc:'Cheating by personation using any communication device or computer resource. The catch-all provision for phishing, vishing, fake-KYC fraud, fake-customer-care scam, fake-CBI / digital-arrest scam, deepfake voice / video impersonation, romance scams, and pig-butchering investment fraud.', pen:'Up to 3 years and fine up to ₹1 lakh', cog:'Y', bail:'Y', court:'Magistrate',
    related:['BNS § 318(4)','BNS § 319'],
    notes:'Almost every modern online-fraud FIR pairs §66D with BNS §318 / §319.'},
  {num:'§ 66E', title:'Violation of privacy (visual)', desc:'Intentionally or knowingly capturing, publishing or transmitting the image of a private area of any person without consent under circumstances violating privacy. "Private area" = naked or undergarment-clad genitals, pubic area, buttocks, female breast.', pen:'Up to 3 years and/or fine up to ₹2 lakh', cog:'Y', bail:'Y', court:'Magistrate',
    related:['BNS § 77 (voyeurism)','Indecent Representation of Women Act'],
    notes:'Used heavily for MMS leaks, hidden-camera footage in changing rooms / washrooms, and revenge-porn cases.'},
  {num:'§ 66F', title:'Cyber terrorism', desc:'Acts intended to threaten the unity, integrity, security or sovereignty of India or to strike terror in the people, by — (i) denying access to authorised users, (ii) attempting to penetrate / access a protected system without authorisation, or (iii) introducing contaminant — and thereby causing or likely to cause death/injury, damage to property, disruption of essential supplies / services, or affecting Critical Information Infrastructure. Also covers knowingly accessing data restricted on grounds of sovereignty / security and using it to cause damage.', pen:'Imprisonment which may extend to LIFE', cog:'Y', bail:'N', court:'Sessions Court (NIA Special Court if NIA Act invoked)',
    related:['§ 70 (Protected systems)','UAPA 1967','BNS § 152'],
    notes:'NIA has concurrent jurisdiction. Investigated as a Scheduled Offence under the NIA Act.'},
  {num:'§ 67', title:'Publishing/transmitting obscene material in electronic form', desc:'Publishing or transmitting any material in electronic form which is lascivious, appeals to prurient interest, or tends to deprave and corrupt persons likely to read/see it. Hicklin / community-standards test imported from §292 IPC.', pen:'1st: up to 3 yrs + ₹5 lakh; subsequent: up to 5 yrs + ₹10 lakh', cog:'Y', bail:'Y', court:'Magistrate',
    cases:['Aveek Sarkar v. State of WB (2014) 4 SCC 257 — community-standards test for online obscenity']},
  {num:'§ 67A', title:'Publishing/transmitting sexually explicit material', desc:'Publishing or transmitting in electronic form any material containing sexually explicit act or conduct. Threshold higher than §67 — requires explicit sexual conduct, not merely lascivious.', pen:'1st: up to 5 yrs + ₹10 lakh; subsequent: up to 7 yrs + ₹10 lakh', cog:'Y', bail:'N', court:'Magistrate of First Class'},
  {num:'§ 67B', title:'Child sexual abuse material (CSAM)', desc:'Publishing, browsing, downloading, advertising, promoting, distributing, exchanging, or facilitating in any electronic form material depicting children in sexually explicit act or conduct, or recording own abuse, or grooming children for online sexual relationships.', pen:'1st: up to 5 yrs + ₹10 lakh; subsequent: up to 7 yrs + ₹10 lakh', cog:'Y', bail:'N', court:'Special Court (POCSO)',
    related:['POCSO Act §13–§15','BNS § 95']},
  {num:'§ 67C', title:'Preservation & retention of information by intermediaries', desc:'Intermediaries must preserve and retain such information in such manner and format and for such duration as the Central Government may prescribe.', pen:'Up to 3 years and fine', cog:'Y', bail:'Y', court:'Magistrate',
    related:['IT Rules 2021 Rule 4(2)']},
  {num:'§ 69', title:'Power to issue directions for interception, monitoring or decryption', desc:'Central / State Government may direct any agency to intercept, monitor or decrypt any information generated, transmitted, received or stored in any computer resource in interest of sovereignty, defence, security, friendly relations, public order, prevention of incitement to a cognizable offence, or for investigation of any offence. Procedure governed by IT (Procedure & Safeguards for Interception) Rules 2009.', pen:'Non-compliance by intermediary: up to 7 years + fine', cog:'—', bail:'—', court:'—',
    cases:['PUCL v. UoI (1997) 1 SCC 301 — telephone tapping safeguards','K.S. Puttaswamy v. UoI (2017) 10 SCC 1 — Right to Privacy']},
  {num:'§ 69A', title:'Power to block public access to information', desc:'Empowers government to block public access to any information generated, transmitted, received, stored or hosted in any computer resource on grounds analogous to Article 19(2) of the Constitution. Procedure under IT Blocking Rules 2009. Confidentiality of blocking orders provided in Rule 16.', pen:'Intermediary non-compliance: up to 7 years + fine', cog:'—', bail:'—', court:'Designated Officer / Review Committee',
    cases:['Shreya Singhal v. UoI (2015) — upheld §69A but read in procedural safeguards']},
  {num:'§ 69B', title:'Power to authorise monitoring & collection of traffic data', desc:'Central Government may authorise any agency to monitor / collect traffic data or information generated, transmitted, received or stored in any computer resource — for cybersecurity, identifying / tracking / blocking incidents.', pen:'Intermediary non-compliance: up to 3 years + fine', cog:'—', bail:'—', court:'—',
    related:['IT (Monitoring & Collection of Traffic Data) Rules 2009']},
  {num:'§ 70', title:'Protected systems', desc:'Government may declare any computer resource that directly or indirectly affects the facility of Critical Information Infrastructure (CII) as a "protected system". CII = computer resource the destruction of which has debilitating impact on national security, economy, public health or safety. Unauthorised access is an aggravated offence.', pen:'Up to 10 years and fine', cog:'Y', bail:'N', court:'Sessions',
    related:['NCIIPC','§ 66F'],
    notes:'Notified protected sectors: Power, Banking & Finance, Telecom, Transport, Govt, Strategic & Public Enterprises, Health.'},
  {num:'§ 70A / 70B', title:'NCIIPC & CERT-In', desc:'§70A designates a nodal agency for CII protection — operationalised as the National Critical Information Infrastructure Protection Centre (NCIIPC) under NTRO. §70B(1) designates CERT-In as the national agency for cybersecurity incidents. §70B(6) — direction power — basis of CERT-In Apr 2022 directions on 6-hr incident reporting and 180-day log retention.', pen:'§70B(7): Non-compliance up to 1 year and/or ₹1 lakh', cog:'Y', bail:'Y', court:'Magistrate',
    related:['CERT-In Directions Apr 2022','NCIIPC Rules 2014']},
  {num:'§ 71', title:'Penalty for misrepresentation to CCA / Certifying Authority', desc:'Misrepresentation or suppression of material fact for obtaining a Digital Signature Certificate (DSC) / electronic signature certificate / licence under the Act.', pen:'Up to 2 years and/or ₹1 lakh', cog:'N', bail:'Y', court:'Magistrate'},
  {num:'§ 72', title:'Breach of confidentiality and privacy', desc:'Any person who has secured access to any electronic record, register, correspondence, information, document or other material under powers conferred by the Act / rules / regulations and discloses it to any other person without consent.', pen:'Up to 2 years and/or fine up to ₹1 lakh', cog:'N', bail:'Y', court:'Magistrate',
    notes:'Limited to officers exercising statutory powers; for body-corporate disclosures see §72A.'},
  {num:'§ 72A', title:'Disclosure of information in breach of lawful contract', desc:'Disclosure of personal information by any person — including intermediary — that is obtained while providing services under a lawful contract, with intent to cause / knowing it likely to cause wrongful loss/gain, without consent of the person concerned, or in breach of contract.', pen:'Up to 3 years and/or fine up to ₹5 lakh', cog:'Y', bail:'Y', court:'Magistrate',
    related:['BNS § 316 (criminal breach of trust)','DPDP Act']},
  {num:'§ 75', title:'Extra-territorial application', desc:'The Act applies to any offence or contravention committed outside India by any person if the act involves a computer, computer system or computer network located in India.', pen:'—', cog:'—', bail:'—', court:'—'},
  {num:'§ 78', title:'Investigating power', desc:'Notwithstanding anything in the BNSS, a police officer not below the rank of Inspector shall investigate any offence under the Act.', pen:'—', cog:'—', bail:'—', court:'—'},
  {num:'§ 79', title:'Intermediary safe harbour', desc:'Conditional immunity to intermediaries (ISPs, social media, search engines, e-commerce, cloud, telecom, app stores) for third-party content if (i) function limited to access, (ii) no initiating, modifying or selecting the receiver, and (iii) due-diligence under IT Rules 2021 observed. Lost on actual knowledge or government / court order to remove and failure to comply within 36 hours.', pen:'Loss of safe harbour exposes intermediary to underlying offence', cog:'—', bail:'—', court:'—',
    cases:['Shreya Singhal v. UoI (2015) — read down §79(3)(b) to require court / govt order','MySpace v. Super Cassettes (2016, Del HC DB)','Kunal Kamra v. UoI (Bom HC 2024) — Fact-Check Unit struck down'],
    notes:'Withdrawal proposed in Digital India Act draft; for now §79 + IT Rules 2021 govern.'},
  {num:'§ 79A', title:'Examiner of Electronic Evidence', desc:'Central Government may notify any Department, body or agency as an Examiner of Electronic Evidence for forensic examination of digital evidence in legal proceedings.', pen:'—', cog:'—', bail:'—', court:'—',
    notes:'CFSL Hyderabad, CFSL Pune, C-DAC are notified examiners.'},
  {num:'§ 81', title:'Overriding effect', desc:'The Act has overriding effect over inconsistent provisions in other laws — except Copyright Act 1957 and Patents Act 1970, which prevail.', pen:'—', cog:'—', bail:'—', court:'—'},
  {num:'§ 84B / 84C', title:'Abetment & attempt', desc:'§84B: abetment of an offence under the Act is punishable with the punishment for the offence. §84C: attempt is punishable with imprisonment up to half the longest term, or fine, or both.', pen:'Same as primary offence (84B); half (84C)', cog:'Y', bail:'follows primary', court:'follows primary'},
  {num:'§ 85', title:'Offences by companies', desc:'When an offence is committed by a company, every person who at the time of offence was in charge of and responsible for the conduct of business — and the company — is deemed guilty, unless they prove the offence was without their knowledge / despite due diligence. Director / manager / officer attribution if consent / connivance / neglect attributable to them.', pen:'Same as primary offence', cog:'follows', bail:'follows', court:'follows',
    notes:'Anchors directors\' & officers\' personal liability for corporate cyber offences.'},
 ]
},

/* ============================================================
   2. BHARATIYA NYAYA SANHITA (BNS), 2023
   ============================================================ */
{
 id:'bns', kind:'bns', short:'BNS', year:'2023 (in force from 1 July 2024)',
 title:'Bharatiya Nyaya Sanhita (BNS), 2023',
 sub:'Replaced the Indian Penal Code, 1860 with effect from 1 July 2024. Most cyber-enabled traditional offences — cheating, forgery, criminal intimidation, defamation, voyeurism, stalking — are now prosecuted under BNS sections, almost always invoked alongside the IT Act in cybercrime FIRs. BNS adds explicit recognition of "electronic record" and "communication device" throughout, and a dedicated organised-crime / petty-organised-crime framework that captures cyber-fraud syndicates.',
 sections:[
  {num:'§ 2', title:'Definitions (incl. electronic record)', desc:'Adopts the definition of "electronic record" from §2(1)(t) IT Act. "Document" includes "electronic and digital record". "Property" expressly includes electronic and digital property. "Communication device" added.', pen:'—', cog:'—', bail:'—', court:'—'},
  {num:'§ 61', title:'Criminal conspiracy', desc:'Agreement of two or more persons to do an illegal act, or a legal act by illegal means. Routinely added in multi-accused cyber-fraud, money-mule, and gang ransomware cases.', pen:'Same as the contemplated offence (or up to 6 months / fine / both for non-listed offences)', cog:'follows', bail:'follows', court:'follows'},
  {num:'§ 69', title:'Sexual intercourse by employing deceitful means', desc:'Sexual intercourse with a woman by deceitful means or false promise to marry, employment, promotion, or by suppressing identity. Captures romance / matrimonial-app frauds and fake-identity online relationships. (Not amounting to rape.)', pen:'Up to 10 years and fine', cog:'Y', bail:'N', court:'Sessions'},
  {num:'§ 75', title:'Sexual harassment', desc:'Includes physical contact and advances involving unwelcome sexual overtures, demand for sexual favours, showing pornography against a woman\'s will, or making sexually-coloured remarks — by any means including electronic. Frequently used with IT §67 / §67A.', pen:'§75(2)(i)–(iii): up to 3 years / fine / both; §75(2)(iv): up to 1 year + fine', cog:'Y', bail:'Y', court:'Magistrate'},
  {num:'§ 76', title:'Assault / criminal force with intent to disrobe', desc:'Including digitally circulating images of disrobing — applied to revenge-porn upload and forced-disrobe MMS cases.', pen:'3 to 7 years and fine', cog:'Y', bail:'N', court:'Sessions'},
  {num:'§ 77', title:'Voyeurism', desc:'Watching, capturing or disseminating an image of a woman engaged in a private act in circumstances where she would have a reasonable expectation of privacy. Companion to IT §66E.', pen:'1st: 1–3 yrs + fine; subsequent: 3–7 yrs + fine', cog:'Y', bail:'1st-Y / sub-N', court:'Magistrate / Sessions',
    related:['IT § 66E']},
  {num:'§ 78', title:'Stalking (incl. cyber-stalking)', desc:'Following / contacting / attempting to contact a woman despite clear disinterest, OR monitoring her use of internet, email or any electronic communication. The dedicated cyber-stalking provision.', pen:'1st: up to 3 yrs + fine; subsequent: up to 5 yrs + fine', cog:'Y', bail:'1st-Y / sub-N', court:'Magistrate'},
  {num:'§ 79', title:'Word, gesture, act intended to insult modesty of a woman', desc:'Online lewd messages, comments and DMs continue to be charged here (replacing IPC §509).', pen:'Up to 3 years and fine', cog:'Y', bail:'Y', court:'Magistrate'},
  {num:'§ 95', title:'Hiring / employing / engaging a child to commit an offence', desc:'Used along with IT §67B / POCSO when minors are recruited into mule-account, OTP-fraud, deepfake or CSAM production rackets.', pen:'Min. 3 yrs to up to 10 yrs + fine', cog:'Y', bail:'N', court:'Sessions'},
  {num:'§ 111', title:'Organised crime', desc:'Continuing unlawful activity by a syndicate using violence, intimidation, coercion, fraud, cybercrime, or trafficking — for direct/indirect material benefit. Squarely captures ransomware-as-a-service crews, dark-web marketplaces, deepfake-fraud syndicates, instant-loan-app extortion gangs.', pen:'Min. 5 yrs to LIFE; DEATH if death caused; min. fine ₹5 lakh', cog:'Y', bail:'N', court:'Special / Sessions',
    notes:'Bail under §480 BNSS is harder; needs prosecutor hearing and reasoned order.'},
  {num:'§ 112', title:'Petty organised crime', desc:'Snatching, theft, cheating including UPI/online cheating, cheating on internet, ATM-skimming, ticket-fraud etc., committed by a gang. Offences below the §111 threshold but still organised.', pen:'1 to 7 years and fine', cog:'Y', bail:'N', court:'Sessions'},
  {num:'§ 113', title:'Terrorist act', desc:'Mirrors UAPA §15 — includes act with intent to threaten the unity, integrity, security, economic security or sovereignty of India by any means including electronic. Read with IT §66F for cyber terrorism counts.', pen:'Death / LIFE / 5 yrs–LIFE depending on sub-clause', cog:'Y', bail:'N', court:'NIA Special / Sessions'},
  {num:'§ 152', title:'Acts endangering sovereignty, unity & integrity of India', desc:'Replaces "sedition" §124A IPC. Covers — by words spoken or written, signs, visible representation, electronic communication, financial means — exciting secession / armed rebellion / subversive activities, or encouraging separatist feelings. Online speech is squarely within scope.', pen:'Up to LIFE / 7 years and fine', cog:'Y', bail:'N', court:'Sessions',
    notes:'Bombay HC / Delhi HC have held that mere criticism is not within §152 — incitement element required.'},
  {num:'§ 196', title:'Promoting enmity between groups (online)', desc:'Promoting disharmony / enmity between religious, racial, language or regional groups, by words / signs / visible representation / electronic communication, or doing an act prejudicial to maintenance of harmony. The principal hate-speech / communal-content section. Replaces IPC §153A.', pen:'Up to 3 yrs + fine; up to 5 yrs if at place of worship', cog:'Y', bail:'N', court:'Magistrate / Sessions'},
  {num:'§ 197', title:'Imputations / assertions prejudicial to national integration', desc:'Includes online assertions / imputations against any class of persons by reason of religion / race / language / caste, denying citizenship / promoting disharmony. Captures communally-targeted misinformation campaigns.', pen:'Up to 3 yrs + fine', cog:'Y', bail:'N', court:'Magistrate'},
  {num:'§ 224', title:'False evidence by electronic record', desc:'Fabrication of false electronic record / false evidence in judicial proceeding.', pen:'Up to 7 years and fine', cog:'Y', bail:'Y', court:'Sessions'},
  {num:'§ 303', title:'Theft', desc:'Theft of movable property — invoked for theft of mobile devices, SIM cards, hard drives, dongles, hardware tokens used in cybercrime.', pen:'Up to 3 years and/or fine', cog:'Y', bail:'Y', court:'Magistrate'},
  {num:'§ 305', title:'Theft from dwelling / vehicle / by clerk / servant', desc:'Aggravated form — used where cyber-theft involves an inside actor who has been entrusted with property.', pen:'Up to 7 years and fine', cog:'Y', bail:'N', court:'Magistrate / Sessions'},
  {num:'§ 314', title:'Dishonest misappropriation of property', desc:'Dishonest misappropriation of any movable property, including cryptocurrency, e-wallets, in-app currency, NFTs.', pen:'Up to 2 years and/or fine', cog:'Y', bail:'Y', court:'Magistrate'},
  {num:'§ 316', title:'Criminal breach of trust', desc:'Dishonest misappropriation by a person entrusted with property — applied to insider data theft, employee fund misappropriation, fund-manager / wallet-custodian theft, payment-aggregator misuse.', pen:'§316(2): up to 5 yrs (general); §316(5): up to 10 yrs (banker, agent, attorney, public servant)', cog:'Y', bail:'Y', court:'Magistrate / Sessions'},
  {num:'§ 318', title:'Cheating', desc:'Cheating by deception inducing delivery of property or consent. The principal "online fraud" provision used in nearly every cyber-fraud FIR — UPI fraud, OLX scam, fake job offers, fake-investment apps, phishing, fake-KYC, digital-arrest, courier-parcel scam, gift-card scam, work-from-home scam.', pen:'§318(2): up to 3 yrs + fine; §318(3) (cheating + dishonestly inducing delivery): up to 5 yrs; §318(4): up to 7 yrs + fine', cog:'Y', bail:'Y', court:'Magistrate / Sessions',
    cases:['Sanjay Kumar Kedia v. NCT of Delhi (2014) — online fraud + IT §66'],
    related:['IT § 66D','BNS § 319']},
  {num:'§ 319', title:'Cheating by personation', desc:'Cheating by pretending to be another person or knowingly substituting one for another. Applied to impersonation scams, fake CBI / ED / police callers, fake-customer-care, deepfake voice / video calls, OTP-fraud calls.', pen:'Up to 5 years and fine', cog:'Y', bail:'Y', court:'Magistrate'},
  {num:'§ 320', title:'Dishonestly receiving stolen property', desc:'Dishonestly receiving / retaining stolen property — applied to receivers of stolen credentials, leaked databases, stolen mobile devices.', pen:'Up to 3 years and fine', cog:'Y', bail:'Y', court:'Magistrate'},
  {num:'§ 336', title:'Forgery', desc:'Making a false document or false electronic record — with intent to cause damage, support a claim or title, or commit fraud. Applies to fake screenshots, doctored e-bills, fake admit cards, forged digital signatures.', pen:'§336(2): up to 2 yrs; §336(3): up to 3 yrs (intent to harm reputation); §336(4): up to 7 yrs (intent to cheat)', cog:'Y', bail:'Y', court:'Magistrate'},
  {num:'§ 337', title:'Forgery of records of court / public register / signature', desc:'Aggravated forgery — applied to fake court orders circulated on WhatsApp, fake e-stamp papers, fake bank passbooks.', pen:'Up to 7 years and fine', cog:'Y', bail:'N', court:'Sessions'},
  {num:'§ 338', title:'Forgery of valuable security, will, etc.', desc:'Forgery of a valuable security (cheque, demand draft, e-stamp, share certificate), authority to issue/transfer money, will, or any document purporting to be one.', pen:'Up to LIFE / 10 years and fine', cog:'Y', bail:'N', court:'Sessions'},
  {num:'§ 340', title:'Forged document used as genuine', desc:'Using as genuine any forged electronic record, document or part thereof, knowing or having reason to believe it to be forged.', pen:'Same as forgery (per §336–§339)', cog:'follows', bail:'follows', court:'follows'},
  {num:'§ 351', title:'Criminal intimidation', desc:'Threatening any person with injury to person, reputation or property — applied to cyber-stalking threats, sextortion ("send money or we leak"), ransomware demands, doxxing-with-threat, anonymous threat messages on Telegram / WhatsApp.', pen:'§351(2): up to 2 yrs; §351(3): up to 7 yrs (anonymous threat or threat of grievous hurt / death / chastity)', cog:'§351(2): N / §351(3): Y', bail:'Y', court:'Magistrate',
    related:['IT § 66','BNS § 78']},
  {num:'§ 353', title:'Statements conducing to public mischief', desc:'Making, publishing or circulating any statement, false information, rumour, including by electronic means, which causes alarm to the public, or induces an offence against the State / public tranquillity, or incites class / community against another. The principal "fake-news / misinformation" provision.', pen:'Up to 3 years / fine / both', cog:'Y', bail:'Y', court:'Magistrate',
    notes:'Frequently invoked for viral misinformation during communal incidents and elections.'},
  {num:'§ 356', title:'Defamation', desc:'Online defamation, defamatory tweets / posts / videos targeting an individual or institution. Truth + public good is a defence. Replaces IPC §499/§500.', pen:'Up to 2 years / fine / community service / all', cog:'N', bail:'Y', court:'Magistrate'},
 ]
},

/* ============================================================
   3. INDIAN PENAL CODE, 1860 — LEGACY CYBER SECTIONS
   ============================================================ */
{
 id:'ipc', kind:'ipc', short:'IPC', year:'1860 (largely repealed by BNS, 2023; in force for pre-1 Jul 2024 offences)',
 title:'Indian Penal Code, 1860 — Cybercrime Sections',
 sub:'Historically the parent statute for cyber-enabled traditional offences before BNS. Sections below were the workhorses of cybercrime FIRs registered before 1 July 2024 and remain relevant for ongoing trials, appeals and revisions of pre-BNS cases.',
 sections:[
  {num:'§ 120A / 120B', title:'Criminal conspiracy', desc:'Conspiracy with two or more persons to do an illegal act. Routinely invoked for multi-accused cyber-fraud and gang ransomware cases pre-BNS.', pen:'Same as the contemplated offence', cog:'follows', bail:'follows', court:'follows',
    related:['BNS § 61']},
  {num:'§ 153A', title:'Promoting enmity between groups', desc:'Online communal posts / videos promoting enmity. Mostly migrated to BNS §196.', pen:'Up to 3 yrs + fine', cog:'Y', bail:'N', court:'Magistrate'},
  {num:'§ 292 / 293', title:'Sale of obscene books / objects', desc:'Pre-IT-Act obscenity charge — sale, distribution, public exhibition. Now superseded by IT §67 for electronic content.', pen:'1st: up to 2 yrs + ₹2k; subsequent: up to 5 yrs + ₹5k', cog:'Y', bail:'Y', court:'Magistrate'},
  {num:'§ 354A–D', title:'Sexual harassment, voyeurism, stalking', desc:'§354A sexual harassment, §354B disrobing, §354C voyeurism, §354D stalking (incl. cyber-stalking) — migrated to BNS §75–§78.', pen:'1–7 yrs depending on sub-clause', cog:'Y', bail:'mixed', court:'Magistrate / Sessions'},
  {num:'§ 379', title:'Theft (data / device)', desc:'Theft of computer hardware, mobile, SIM, cryptographic tokens, and historically data treated as movable property.', pen:'Up to 3 years and/or fine', cog:'Y', bail:'Y', court:'Magistrate'},
  {num:'§ 405 / 406', title:'Criminal breach of trust', desc:'Dishonest misappropriation by an insider, employee, fund manager or trusted custodian of digital property.', pen:'Up to 3 years and/or fine', cog:'Y', bail:'Y', court:'Magistrate'},
  {num:'§ 408 / 409', title:'CBT by clerk / servant / public servant', desc:'Aggravated CBT — used in insider data-leak / fund-misappropriation cases.', pen:'§408: up to 7 yrs; §409: up to LIFE', cog:'Y', bail:'N', court:'Sessions'},
  {num:'§ 415 / 417 / 418', title:'Cheating (definitions & general punishment)', desc:'§415 defines cheating. §417 general punishment up to 1 year. §418 cheating with knowledge of likely wrongful loss to special-interest person — up to 3 years.', pen:'§417: up to 1 yr; §418: up to 3 yrs', cog:'§418: Y', bail:'Y', court:'Magistrate'},
  {num:'§ 419', title:'Cheating by personation', desc:'Phishing, fake-KYC calls, impersonation of bank / CBI / courier officials. Migrated to BNS §319.', pen:'Up to 3 years and/or fine', cog:'Y', bail:'Y', court:'Magistrate'},
  {num:'§ 420', title:'Cheating and dishonestly inducing delivery of property', desc:'The classic provision used in nearly every pre-BNS online-fraud FIR — UPI fraud, OLX scam, investment fraud, fake job offers, fake-Customs / RBI calls. Migrated to BNS §318(4).', pen:'Up to 7 years and fine', cog:'Y', bail:'Y', court:'Magistrate / Sessions',
    related:['BNS § 318']},
  {num:'§ 463–471', title:'Forgery & forged electronic record', desc:'§463 defines forgery. §464 making a false document. §465 punishment for forgery. §468 forgery for purpose of cheating. §471 using as genuine a forged document. All read with the IT-Act amendment that "document" includes electronic records.', pen:'Up to 2–10 years and fine', cog:'mixed', bail:'mixed', court:'Magistrate / Sessions'},
  {num:'§ 499 / 500', title:'Defamation', desc:'Online defamation, defamatory social-media posts. Migrated to BNS §356.', pen:'Up to 2 years and/or fine', cog:'N', bail:'Y', court:'Magistrate',
    cases:['Subramanian Swamy v. UoI (2016) 7 SCC 221 — criminal defamation upheld']},
  {num:'§ 503 / 506', title:'Criminal intimidation', desc:'Online threats, sextortion demands, ransomware demands, anonymous threats over messaging apps. Migrated to BNS §351.', pen:'§506(1): up to 2 yrs; §506(2): up to 7 yrs', cog:'mixed', bail:'Y', court:'Magistrate / Sessions'},
  {num:'§ 507', title:'Criminal intimidation by anonymous communication', desc:'Specific aggravation when threat is anonymous — fits messaging-app, dark-web, and burner-account threat cases.', pen:'Up to 2 years (in addition to §506)', cog:'N', bail:'Y', court:'Magistrate'},
  {num:'§ 509', title:'Word/gesture intended to insult modesty of a woman', desc:'Online harassment, lewd messages, comments on social media. Migrated to BNS §79.', pen:'Up to 3 years and fine', cog:'Y', bail:'Y', court:'Magistrate'},
 ]
},

/* ============================================================
   4. DIGITAL PERSONAL DATA PROTECTION ACT, 2023
   ============================================================ */
{
 id:'dpdp', kind:'dpdp', short:'DPDP', year:'2023 (Rules notified 2025)',
 title:'Digital Personal Data Protection Act, 2023',
 sub:'India\'s first horizontal data-protection statute. Applies to processing of digital personal data within India (and to entities outside India offering goods/services to data principals in India). Establishes the Data Protection Board of India (DPBI). Operationalised through the DPDP Rules 2025. Penalties go up to ₹250 crore per breach, imposed by DPBI; appeal lies to TDSAT.',
 sections:[
  {num:'§ 2', title:'Definitions', desc:'Key terms — "personal data", "processing", "Data Principal", "Data Fiduciary", "Data Processor", "consent", "child" (under 18), "digital personal data". No separate category of "sensitive personal data" — single-tier framework.', pen:'—', cog:'—', bail:'—', court:'—'},
  {num:'§ 3', title:'Application', desc:'Applies to processing of digital personal data within India (whether collected digitally or non-digitally and digitised), and outside India if offering goods/services to data principals in India. Excludes: personal/domestic use, publicly available data made public by the data principal or by law.', pen:'—', cog:'—', bail:'—', court:'—'},
  {num:'§ 4', title:'Grounds for processing personal data', desc:'Processing only on (a) consent under §6, or (b) certain legitimate uses under §7. There is no general "legitimate interest" ground — the §7 list is closed.', pen:'See §33', cog:'—', bail:'—', court:'DPBI'},
  {num:'§ 5', title:'Notice', desc:'Itemised notice in clear plain language, including (i) personal data and purpose of processing, (ii) manner of exercising rights under §11–§14, (iii) DPBI complaint mechanism. Multi-language requirement — also in 22 scheduled languages on demand.', pen:'See §33', cog:'—', bail:'—', court:'DPBI'},
  {num:'§ 6', title:'Consent', desc:'Consent must be free, specific, informed, unconditional, unambiguous, with a clear affirmative action. Limited to the specified purpose. Can be withdrawn — must be as easy to withdraw as to give. Negative consequences of withdrawal cannot be visited on data principal.', pen:'See §33', cog:'—', bail:'—', court:'DPBI'},
  {num:'§ 7', title:'Certain legitimate uses', desc:'Voluntary provision for specified purpose; State functions for subsidies/benefits/services/licence/permit; medical emergency; epidemic / public health; disaster; employment-related processing; safety/identity verification of employees in service.', pen:'See §33', cog:'—', bail:'—', court:'DPBI'},
  {num:'§ 8', title:'General obligations of Data Fiduciary', desc:'Accuracy, completeness; security safeguards proportionate to risk; breach notification to DPBI and to each affected data principal; erasure on withdrawal of consent or end of purpose; grievance redressal mechanism; contractual flow-down to Data Processors; data-retention limits per purpose.', pen:'Up to ₹250 crore', cog:'—', bail:'—', court:'DPBI'},
  {num:'§ 9', title:'Processing of children\'s data', desc:'Verifiable parental consent required for any data principal under 18, and consent of lawful guardian for persons with disability. Tracking, behavioural monitoring and targeted advertising directed at children prohibited. Government may notify exemptions for entities processing children\'s data in a "verifiably safe manner".', pen:'Up to ₹200 crore', cog:'—', bail:'—', court:'DPBI'},
  {num:'§ 10', title:'Significant Data Fiduciary (SDF)', desc:'Government may notify a Data Fiduciary as SDF based on volume / sensitivity of data, risk to rights of data principals, potential impact on sovereignty, electoral democracy, security of State and public order. SDF must (i) appoint India-resident Data Protection Officer reporting to Board, (ii) appoint independent data auditor, (iii) undertake periodic Data Protection Impact Assessment (DPIA), (iv) periodic audit, (v) other measures notified.', pen:'Up to ₹250 crore', cog:'—', bail:'—', court:'DPBI'},
  {num:'§ 11', title:'Right to information about personal data', desc:'Data principal has right to obtain summary of personal data being processed and processing activities, identities of all data fiduciaries / processors with whom shared, and any other information prescribed.', pen:'See §33', cog:'—', bail:'—', court:'DPBI'},
  {num:'§ 12', title:'Right to correction & erasure', desc:'Right to correction, completion, updation, erasure of inaccurate / incomplete / outdated / no-longer-necessary personal data.', pen:'See §33', cog:'—', bail:'—', court:'DPBI'},
  {num:'§ 13', title:'Right of grievance redressal', desc:'Right to readily-available grievance redressal mechanism. Complaint to DPBI lies only after Data Fiduciary fails to redress.', pen:'See §33', cog:'—', bail:'—', court:'DPBI'},
  {num:'§ 14', title:'Right to nominate', desc:'Right to nominate any other individual who shall, in the event of death or incapacity of the data principal, exercise the rights under the Act.', pen:'See §33', cog:'—', bail:'—', court:'DPBI'},
  {num:'§ 15', title:'Duties of Data Principal', desc:'Includes — (i) compliance with applicable laws, (ii) furnishing only authentic information, (iii) not impersonating another, (iv) not suppressing material info, (v) not lodging false / frivolous complaints. Penalty up to ₹10,000 — small but unique among data-protection laws globally.', pen:'Up to ₹10,000 per violation', cog:'—', bail:'—', court:'DPBI'},
  {num:'§ 16', title:'Cross-border transfer', desc:'Personal data may be transferred outside India except to countries notified by the Central Government on a "negative list". Sectoral law (e.g. RBI / SEBI / IRDAI) prevails if stricter.', pen:'Sectoral law if stricter prevails', cog:'—', bail:'—', court:'DPBI'},
  {num:'§ 17', title:'Exemptions', desc:'Limited exemptions — (1) prevention/investigation/prosecution of offence, (2) court order, (3) processing for arbitral / judicial / regulatory function, (4) ascertaining financial info of debt-defaulter, (5) processing in interest of sovereignty, security, public order — by notified state instrumentalities, (6) research/archiving/statistical purposes (excl. decisional impact on the principal), (7) start-ups (notified). Storage limitation under §8(7)/(8) waived for state instrumentalities.', pen:'—', cog:'—', bail:'—', court:'—'},
  {num:'§ 18–26', title:'Data Protection Board of India — establishment & functions', desc:'§18 establishes DPBI as a digital-by-design body. §19 composition. §20 disqualifications. §21 procedure. §22 duties. §23 budget. §24 grants from CG. §25 audit. §26 annual report. Members appointed by Central Government — independence concerns flagged by stakeholders.', pen:'—', cog:'—', bail:'—', court:'DPBI'},
  {num:'§ 27–28', title:'Powers of DPBI', desc:'§27: directs remedial / mitigation measures, blocks information access in interim, summons production. §28: inquiry powers — civil-court powers under CPC for summons, examining on oath, requiring production. Inquiry on receipt of complaint, reference, court direction, or suo-motu.', pen:'—', cog:'—', bail:'—', court:'DPBI'},
  {num:'§ 29', title:'Appeal to TDSAT', desc:'Appeal from any DPBI order lies to Telecom Disputes Settlement and Appellate Tribunal (TDSAT) within 60 days; further appeal to Supreme Court on substantial question of law under §31.', pen:'—', cog:'—', bail:'—', court:'TDSAT'},
  {num:'§ 33 + Schedule', title:'Penalties (monetary)', desc:'Schedule of monetary penalties: ₹250 cr (failure to safeguard / breach notification under §8), ₹200 cr (children\'s data §9, SDF additional duties §10), ₹150 cr (data-principal duties §15 — applicable to fiduciary not principal cap), ₹50 cr (notice / consent breaches), ₹10,000 (§15 data-principal violations).', pen:'Up to ₹250 crore per breach', cog:'—', bail:'—', court:'DPBI'},
  {num:'§ 39 / 44', title:'Repeal & amendments', desc:'§39 repeals IT §43A and SPDI Rules 2011 to the extent inconsistent. §44 amends RTI §8(1)(j) to substantially restrict disclosure of personal information.', pen:'—', cog:'—', bail:'—', court:'—',
    notes:'§44 has drawn criticism for weakening transparency law.'},
 ]
},

/* ============================================================
   5. RULES, SECTORAL & ADJACENT LAWS
   ============================================================ */
{
 id:'other', kind:'other', short:'Other', year:'Various',
 title:'Rules, Sectoral & Adjacent Statutes',
 sub:'Sectoral, procedural, and supporting statutes that frequently appear in cybercrime cases, regulatory action, and cybersecurity compliance — covering Rules under the IT/DPDP Acts, evidence and procedure codes, financial-sector regulators, telecom, money-laundering, copyright, child-safety, and identity laws.',
 sections:[
  {num:'IT Rules, 2021', title:'Intermediary Guidelines & Digital Media Ethics Code', desc:'Due-diligence obligations on intermediaries (Part II); additional obligations on Significant Social Media Intermediaries (>50 lakh registered users) — appoint Chief Compliance Officer, Nodal Contact Person (24×7), Resident Grievance Officer, enable traceability of first originator (messaging), publish monthly compliance reports, takedown within 36 hours of court / govt order, 24 hours for sexual content. Part III imposes a 3-tier code on digital news publishers and OTT.', pen:'Loss of §79 safe harbour', cog:'—', bail:'—', court:'Civil / writ courts',
    cases:['WhatsApp v. UoI (Del HC, pending) — traceability challenge','Kunal Kamra v. UoI (Bom HC 2024) — Fact-Check Unit struck down']},
  {num:'IT Amendment Rules 2022 / 2023', title:'Grievance Appellate Committees & FCU', desc:'2022 amendments: 3-member Grievance Appellate Committees (GAC) to hear user complaints against social media intermediary decisions. 2023 amendments: empowered MeitY-notified Fact-Check Unit (FCU) to flag govt-related "fake / false / misleading" content for removal — struck down by Bom HC (Kunal Kamra, 2024).', pen:'GAC orders binding on intermediary', cog:'—', bail:'—', court:'GAC / writ'},
  {num:'CERT-In Directions, 28 Apr 2022', title:'§70B(6) Cybersecurity Directions', desc:'Mandatory reporting of 20 categories of incidents to CERT-In within 6 hours of noticing — incl. data breach, ransomware, defacement, identity theft, DoS/DDoS, BGP hijack, fake mobile app, MITM. 180-day log retention in India. 5-year KYC retention by VPN, VPS, cloud, virtual asset service providers, crypto-exchanges. NTP sync to NIC/NPL. Designated Point of Contact (POC).', pen:'Up to 1 year and/or ₹1 lakh under §70B(7)', cog:'Y', bail:'Y', court:'Magistrate'},
  {num:'IT (Reasonable Security Practices) Rules 2011 [SPDI Rules]', title:'SPDI processing & ISO 27001', desc:'Rules under §43A. Defines SPDI (passwords, financial info, health, biometrics, sexual orientation, etc.). Requires privacy policy, prior consent, purpose limitation, data subject access. ISO/IEC 27001 (or equivalent code certified by CG) presumed to be "reasonable security practices". Largely superseded by DPDP §8 once notified.', pen:'§43A compensation', cog:'—', bail:'—', court:'Adjudicating Officer'},
  {num:'IT (Interception) Rules 2009', title:'§69 Procedure & Safeguards for Interception, Monitoring, Decryption', desc:'Authorisation by Union/State Home Secretary; in unavoidable circumstances, by Joint-Secretary-rank officer authorised by Home Secretary; ratification within 7 days. Review Committee meets every 2 months. 60-day max validity per direction (extensions up to 180 days).', pen:'§69 + §72 penalties', cog:'—', bail:'—', court:'—'},
  {num:'IT (Blocking) Rules 2009', title:'§69A Procedure & Safeguards for Blocking', desc:'Designated Officer (Director-rank) processes nodal-officer requests; Committee for Examination of Request (CER) recommends; emergency blocking within 24 hrs by Secretary, MeitY (ratification within 48 hrs). Rule 16 mandates strict confidentiality of blocking orders — held constitutionally valid in Shreya Singhal but contested in subsequent litigation.', pen:'Intermediary non-compliance: §69A(3)', cog:'—', bail:'—', court:'—'},
  {num:'IT (Traffic Data) Rules 2009', title:'§69B Monitoring & Collection of Traffic Data', desc:'Authorisation by Secretary, MeitY. Cybersecurity-purpose monitoring distinct from §69 interception. Confidentiality and destruction of records after 9 months unless required.', pen:'§69B + §72', cog:'—', bail:'—', court:'—'},
  {num:'NCIIPC Rules, 2014', title:'Critical Information Infrastructure Protection', desc:'Notified under §70A. NCIIPC under NTRO is the nodal agency for protected sectors — Power, Banking & Finance, Telecom, Transport, Govt, Strategic & Public Enterprises, Health. Mandates baseline security, sectoral CERT coordination, periodic audit, table-top exercises.', pen:'§70 unauthorised access: up to 10 yrs', cog:'Y', bail:'N', court:'Sessions'},
  {num:'DPDP Rules, 2025', title:'Operational Rules under DPDP Act 2023', desc:'Notified rules — manner of consent notice, verifiable parental consent (VPC), reasonable security safeguards (encryption / access control / log retention 1 year / VAPT), breach-notification timelines (intimation to DPBI within 72 hrs of becoming aware), data retention triggers (3-yr for e-commerce / online gaming / social-media), consent manager registration & obligations, SDF criteria & DPO requirements.', pen:'See DPDP §33', cog:'—', bail:'—', court:'DPBI'},
  {num:'BNSS 2023, §94 / §95 / §185', title:'Bharatiya Nagarik Suraksha Sanhita — digital seizure', desc:'Successor to CrPC. §94 empowers police / court to require production of any "document, electronic communication, including electronic record" — basis of digital preservation / production orders. §95 covers search. §185 introduces electronic-evidence preservation safeguards. §530 mandates trial / inquiry / proceeding in electronic mode where feasible.', pen:'Procedural', cog:'—', bail:'—', court:'—'},
  {num:'BSA 2023, §61–§63', title:'Bharatiya Sakshya Adhiniyam, 2023 (Evidence)', desc:'Replaces Indian Evidence Act, 1872. §61 expressly recognises electronic / digital records as primary evidence and on equal footing with paper. §62 defines secondary evidence. §63 prescribes the certificate framework (replacing IEA §65B) for admissibility of electronic evidence — certificate of authenticity from person in charge of computer + expert (where required).', pen:'Procedural', cog:'—', bail:'—', court:'—',
    cases:['Anvar P.V. v. P.K. Basheer (2014) 10 SCC 473','Arjun Panditrao Khotkar v. Kailash Kushanrao (2020) 7 SCC 1']},
  {num:'PMLA, 2002', title:'Prevention of Money Laundering Act', desc:'Invoked by ED in large cyber-fraud cases — crypto-money-laundering, illicit gaming apps, instant-loan-app extortion, mule-account networks. Predicate (scheduled) offences include IT Act §§ 66, 66E, 66F, 67, 67A, 67B, 70, 72A, and BNS §§ 111, 112, 318, 319, 336–340. Crypto exchanges and VDA service providers are "Reporting Entities" under §2(wa) since 7 March 2023.', pen:'3 to 7 years (up to 10 in narcotics) + attachment', cog:'Y', bail:'N (twin-test §45)', court:'PMLA Special Court'},
  {num:'Telecom Act, 2023', title:'Bharatiya Telecommunication Adhiniyam, 2023', desc:'Replaces Indian Telegraph Act 1885 + Wireless Telegraphy Act 1933. §20 unauthorised interception, §22 obstruction, §28 punishment for SIM-fraud / fake-identity SIM, §42 power to take measures for cybersecurity in public emergencies / interest of public safety. Power to intercept and to suspend messages. Defines "telecommunication" widely (potentially incl. OTT, contested).', pen:'Up to 3 years and/or fine up to ₹2 cr (sectoral); ₹50 lakh per SIM-fraud incident', cog:'Y', bail:'mixed', court:'Magistrate / Sessions',
    notes:'TRAI ↔ TSP fraud-management directions and Sanchar-Saathi portal sit under this Act.'},
  {num:'Telecom Cybersecurity Rules, 2024', title:'TSP cybersecurity baseline', desc:'Mandatory cybersecurity policy, CISO appointment, telecom-security-incident report to nodal officer within prescribed timelines, vulnerability disclosure framework, audits.', pen:'License-condition penalties', cog:'—', bail:'—', court:'DOT'},
  {num:'RBI Master Directions', title:'Cybersecurity & Digital Payment Security', desc:'(i) Cyber Security Framework for Banks (2 Jun 2016); (ii) Master Direction on Digital Payment Security Controls (18 Feb 2021) — applicable to SCBs, SFBs, Payment Banks, NBFC-D, credit-card issuers; (iii) Master Direction on Outsourcing of IT Services by REs (2023); (iv) Customer-liability framework for unauthorised electronic banking transactions (2017) — zero-liability if reported within 3 days. Mandatory SOC, VAPT, RTBC, BCP/DR.', pen:'RBI monetary penalty + business restrictions', cog:'—', bail:'—', court:'RBI'},
  {num:'SEBI CSCRF, 2024', title:'Cybersecurity & Cyber Resilience Framework for REs', desc:'Mandatory framework for SEBI-regulated entities — stock exchanges, depositories, MIIs, brokers, MFs, AIFs, REITs/InvITs, KRAs, RTAs. Covers governance (board oversight), IAM, network security, application security, VAPT, SOC (incl. M-SOC for smaller REs), red-teaming, cybersecurity audit, mandatory reporting, disclosures. Phased rollout 2024–25.', pen:'SEBI penalty + §11 / §15HB action', cog:'—', bail:'—', court:'SEBI / SAT'},
  {num:'IRDAI Cybersecurity Guidelines, 2023', title:'Insurance-sector cybersecurity', desc:'Information & Cyber Security Guidelines 2023 — applicable to insurers and intermediaries; mandates governance, ISMS aligned to ISO 27001, ICT outsourcing controls, cyber-crisis management plan, periodic VAPT, incident reporting to IRDAI.', pen:'IRDAI penalty', cog:'—', bail:'—', court:'IRDAI'},
  {num:'Copyright Act, 1957', title:'Software & content piracy', desc:'§63: imprisonment 6 months–3 yrs + ₹50k–₹2 lakh for infringement of copyright. §63B: knowing use of infringing computer programs — same penalty. §65: making/possessing plates for infringing copies. Applied to source-code theft, pirated software audits, online streaming piracy, ROM-hacking cases.', pen:'Up to 3 years and ₹2 lakh (1st conviction)', cog:'Y', bail:'Y', court:'Magistrate of First Class'},
  {num:'POCSO Act, 2012', title:'Protection of Children from Sexual Offences', desc:'§13–§15: use of child for pornographic purposes / storage / publication of CSAM. Read with IT Act §67B and BNS §95. Cognizable, non-bailable; mandatory reporting under §19 and §20 (intermediary obligation under IT Rules 2021 to report CSAM to NCMEC and NCRB CCTNS / NCMEC tipline).', pen:'§13: up to 5 yrs (1st) / 7 yrs (sub.); §14 aggravated assault: up to LIFE', cog:'Y', bail:'N', court:'Special POCSO Court'},
  {num:'Indecent Representation of Women (Prohibition) Act, 1986', title:'Online morphed images & deepfakes', desc:'§3 prohibition of indecent representation of women through advertisements, publications, writings, paintings, figures or "in any other manner". §4 prohibition of producing / distributing such content. Applied to morphed images, MMS leaks, deepfake pornography along with IT Act §§66E, 67, 67A.', pen:'1st: up to 2 yrs + ₹2k; subsequent: 6 mo–5 yrs + ₹10k–₹1 lakh', cog:'Y', bail:'Y', court:'Magistrate'},
  {num:'Aadhaar Act, 2016', title:'Aadhaar (Targeted Delivery of Subsidies)', desc:'§29 restrictions on sharing identity info. §37 disclosure of identity info / authentication record (1st info & UIDAI consent required). §38 unauthorised access to CIDR. §40 tampering with data in CIDR. §42 general penalty. Read with IT Act §66 / §66C for Aadhaar-fraud and biometric-cloning cases.', pen:'§38 (CIDR hack): up to 10 yrs + min ₹10 lakh', cog:'Y', bail:'N', court:'Sessions'},
  {num:'Companies Act, 2013', title:'Cybersecurity governance', desc:'§134(5)(e) directors\' responsibility statement re. internal financial controls — IT controls implicit. §177 Audit Committee oversight of IT systems and risk management. §134(3)(n) risk-management report. CARO 2020 cl. (3)(xi)(c) audit reporting on cyber-incidents reported to RBI/SEBI. SEBI-LODR Reg. 30 + Sch. III mandates disclosure of material cyber incidents to stock exchanges.', pen:'Officer-in-default penalties; shareholder action', cog:'—', bail:'—', court:'NCLT / Registrar'},
  {num:'Negotiable Instruments Act, 1881 §138', title:'Cheque dishonour (in cyber-fraud chains)', desc:'Cheque-dishonour offences are routinely added when fraud proceeds were partly settled by cheque, or when refund cheques bounce in pig-butchering / Ponzi cases.', pen:'Up to 2 years + 2× cheque amount', cog:'N', bail:'Y', court:'Magistrate'},
  {num:'Foreign Exchange Management Act, 1999', title:'FEMA — cross-border crypto / fund flows', desc:'§3 prohibition of unauthorised forex transactions; §4 holding foreign exchange / property; §13 contraventions — applied to unauthorised crypto remittances, hawala via mule accounts, forex-trading-app frauds. ED enforces.', pen:'Up to 3× sum involved + interest', cog:'—', bail:'—', court:'Adjudicating Authority'},
  {num:'UAPA, 1967', title:'Unlawful Activities (Prevention) Act', desc:'§15 terrorist act read with IT §66F and BNS §113 — for cyber-terror, ICS / OT attacks on CII, terror-financing via crypto, online radicalisation. NIA jurisdiction.', pen:'§16: 5 yrs–LIFE (death if death caused)', cog:'Y', bail:'N (§43D twin-test)', court:'NIA Special Court'},
  {num:'Consumer Protection Act, 2019 + E-Commerce Rules 2020', title:'E-commerce platform liability', desc:'Defines "e-commerce entity" and imposes duties — display seller details, country of origin, grievance officer; prohibition of unfair trade practices, misleading ads, dark patterns (Dark Patterns Guidelines 2023). Class-action by central authority (CCPA).', pen:'CCPA fines + product liability + class-action damages', cog:'—', bail:'—', court:'CCPA / Consumer Commission'},
  {num:'Gaming-related laws', title:'Online gaming framework', desc:'IT Rules 2021 (3rd Amdt) introduced obligations on online-gaming intermediaries; Self-Regulatory Bodies (SRBs) provision was notified but has been on hold. State enactments (TN, Karnataka, AP, Telangana) regulate / ban online real-money games. GST 28% on full face-value of online gaming since Oct 2023.', pen:'Sectoral + IT-Act intermediary penalties', cog:'—', bail:'—', court:'mixed'},
  {num:'NIA Act, 2008 — Schedule', title:'NIA jurisdiction over cyber offences', desc:'IT §66F (cyber terrorism) is a Scheduled Offence under the NIA Act — National Investigation Agency has concurrent investigative jurisdiction across states. Designated NIA Special Courts try the offence.', pen:'Procedural', cog:'—', bail:'—', court:'NIA Special'},
  {num:'Mutual Legal Assistance & Treaties', title:'Cross-border cooperation', desc:'India is not a signatory to the Budapest Convention on Cybercrime (2001), but cooperates via bilateral MLATs (e.g. India-US MLAT 2005), 24/7 INTERPOL channel, and direct govt-to-platform requests. Letters Rogatory under §188 BNSS for foreign evidence.', pen:'Procedural', cog:'—', bail:'—', court:'—'},
  {num:'Public Records Act, 1993', title:'Govt-record handling & retention', desc:'Read with IT Act §4: electronic records of govt offices to be preserved per record-retention schedules; destruction without authority is an offence (§9: up to 5 yrs / ₹10k).', pen:'Up to 5 years and/or ₹10,000', cog:'—', bail:'—', court:'Magistrate'},
  {num:'IT Act, §1(2) + §75', title:'Extra-territorial jurisdiction', desc:'The Act applies to any offence committed outside India by any person if the act involves a computer, computer system or computer network located in India — basis for proceedings against overseas threat actors and offshore call-centre fraud kingpins.', pen:'As per offence', cog:'follows', bail:'follows', court:'follows'},
 ]
}
];
